import React, { useEffect, useId, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import './configuratorManual.css';
import { Figure } from './manualFigures';

const chapters = [
  { title: 'Introduzione e percorso', subtitle: 'A cosa serve e in che ordine si lavora', intro: 'Il Configuratore Iniziative serve a trasformare una richiesta di Poste (un’iniziativa con il suo codice GOTO) in una valutazione completa: capisce cosa va fatto, lo motiva con razionali e vincoli, lo traduce in interventi a catalogo, calcola l’offerta economica e produce la Tabella di offerta in Excel. Al termine la valutazione passa all’applicazione Sviluppo iniziative, che la porta fino al codice. Si lavora in quattro passi: Iniziativa, Interventi, Offerta, Revisione.', figure: { id: 'configurator', title: 'Figura 1 — Il percorso.', caption: 'Cosa porti, i quattro passi con ciò che fai e ottieni in ciascuno, e i tre modi di salvare.', alt: 'La figura ha tre fasce, dall’alto in basso. Prima fascia, cosa porti: la Tabella di Offerta in Excel, i dati inseriti a mano (GOTO, titolo, sistema), il workspace documentale, i razionali e vincoli con l’AI, la soluzione per Visual Studio Code, lo storico e la conoscenza storica AI. Seconda fascia, quattro passi in sequenza. Passo 1 Iniziativa: compili i dati e importi l’Excel, apri le sezioni, premi Analizza e suggerisci; ottieni il contesto e le voci suggerite. Passo 2 Interventi: scegli le voci di catalogo, imposti tipo, complessità e quantità, chiedi il Secondo parere AI; ottieni l’elenco degli interventi scelti. Passo 3 Offerta: controlli prezzi e confronto Excel, imposti sconto e contingenza, regoli le TOW automatiche e inserisci le manuali; ottieni il totale offerta. Passo 4 Revisione: leggi il riepilogo, generi la Tabella di offerta XLSX, esporti JSON e CSV, salvi la valutazione; ottieni i file pronti e la valutazione salvata. Terza fascia, come salvi: Salva valutazione registra l’offerta e aggiorna lo storico dell’analisi; Salva e Chiudi salva e svuota la pagina solo se il salvataggio riesce; Salva e vai a Sviluppo apre Sviluppo iniziative sulla stessa iniziativa. Regola: per salvare serve almeno il GOTO o il titolo, il salvataggio completo richiede il Codice GOTO, e Reset non chiede conferma.' }, steps: [
    'Accedi con un ruolo Developer o SuperAdmin: sono i soli che vedono il Configuratore nella Home. Controlla in alto il contratto e il lotto: sono mostrati nell’intestazione fissa insieme al Codice GOTO e al titolo.',
    'Per riprendere un lavoro apri «Archivio iniziative» (nella card «Il tuo spazio di lavoro») e clicca una scheda; per cominciare da zero premi «+ Nuova Iniziativa». Se hai già dati nella pagina, l’app chiede conferma prima di sostituirli.',
    'Passo 1 «Iniziativa»: compila i dati (Codice GOTO, Titolo, Sistema, Release, PM Poste) oppure importa la Tabella di Offerta. Quando hai almeno GOTO o titolo si sbloccano Workspace documentale, Razionali e vincoli, Soluzione e Analisi condivisa.',
    'Passo 2 «Interventi»: scegli quali voci di catalogo servono, con tipo, complessità e quantità. Premi «Secondo parere AI» per avere proposte da valutare. Poi il pulsante «Vai all’offerta» (mostra tra parentesi quante voci hai selezionato).',
    'Passo 3 «Offerta»: controlla prezzi, sconto, contingenza e le TOW automatiche e manuali. Passo 4 «Revisione»: verifica il riepilogo, genera l’Excel, salva con «Salva valutazione».',
    'Quando la valutazione è pronta premi «Salva e vai a Sviluppo →» per proseguire con le schede per attività e il codice. La collaborazione e le revisioni sono spiegate più avanti in questo manuale, nei capitoli Analisi e conversazione e Revisioni e collaborazione.',
  ], note: 'Il Codice GOTO collega storico, allegati, razionali e conversazione nell’ambiente attivo. Per mantenere separati lavori distinti usa GOTO distinti. Ogni passo ha un segno ✓ quando contiene dati; il passo 4 non lo mostra mai.' },
  { title: 'Passo 1 · Dati dell’iniziativa', subtitle: 'Cosa compilare e in che ordine', intro: 'Il passo Iniziativa raccoglie tutto ciò che identifica e descrive la richiesta. Qui nasce il legame con il resto del lavoro: il Codice GOTO collega documenti, razionali, analisi, storico e sviluppo. Compila prima i dati essenziali, poi usa le altre sezioni per arricchirli.', steps: [
    'Apri la sezione 1 «Dati iniziativa» (è la sola aperta all’avvio). Se mancano sia GOTO sia titolo la riga mostra «Da compilare».',
    'Se hai già la Tabella di Offerta di Poste, premi «Importa Tabella di Offerta» (in alto a destra nella sezione) e scegli il file .xlsx con il foglio ID_INTERVENTO e il foglio DettaglioInterventi: compila da solo Codice GOTO, Titolo, Sistema, requisiti e descrizione, se presenti nel file.',
    'Altrimenti compila a mano i campi della tabella qui sotto. Poi premi «Analizza e suggerisci»: l’app propone fino a 10 voci a partire da titolo, sistema e descrizione (le prime 4 sono già selezionate) e ti porta al passo 2. Con meno di 20 caratteri utili di descrizione ti chiede di scrivere di più.',
    'Con interventi importati il pulsante cambia in «Analizza integrazioni (N interventi)» e cerca le voci mancanti rispetto al catalogo, invece di ripartire dal testo.',
    '«Reset» azzera in un colpo iniziativa, interventi, offerta, proposte AI e applicativi scelti e ti riporta al passo 1: non chiede conferma, quindi usalo solo dopo aver salvato.',
  ], fields: { caption: 'Campi della sezione «Dati iniziativa»', rows: [
    ['Codice GOTO', 'Il codice dell’iniziativa. Non è obbligatorio per scrivere, ma serve per il salvataggio completo di offerta e storico.'],
    ['Titolo', 'Il titolo dell’iniziativa. Insieme al GOTO compare nell’intestazione fissa.'],
    ['Sistema / applicazione', 'Si compila dall’Excel importato o da «Apri nel Configuratore» dello Storico. Con «+ Aggiungi applicativo…» scegli uno o più applicativi come chip rimovibili (×): servono a trovare il profilo tecnico e le proposte AI.'],
    ['Tipo contratto', 'Selezione tra le modalità disponibili (ad esempio BASE o QDO); «— nessuno —» se non applicabile.'],
    ['Release', 'Scegli una release dall’elenco, «Da pianificare», «TBD (To Be Defined)» o «Altro (testo libero)…». Se l’elenco non è disponibile il campo diventa di testo.'],
    ['PM Poste', 'Scegli il nome dall’elenco già usato in MEV e MEV-CAP, oppure «Altro (testo libero)…». Resta salvato con l’offerta e con le revisioni.'],
    ['Requisiti', 'Testo libero: cosa chiede Poste.'],
    ['Descrizione', 'Testo libero più ampio; «⤢ Espandi» lo apre in una finestra per scrivere con comodità.'],
  ] }, warnings: [
    ['Le sezioni 2–5 risultano «Bloccato».', 'Mancano sia GOTO sia titolo: inseriscine almeno uno.'],
    ['«Inserisci una descrizione più dettagliata».', 'L’analisi dal testo richiede almeno 20 caratteri non vuoti tra titolo, sistema e descrizione.'],
    ['«Il lotto del file non è disponibile nel contratto selezionato».', 'Il file Excel è di un lotto diverso: cambia contratto o lotto in «Risorse e configurazione» prima di importare.'],
    ['«Excel importato, ma revisione non salvata».', 'I dati restano nella pagina: salva una revisione dal workspace dopo aver controllato lo storico.'],
  ], note: 'L’importazione salva da sola una revisione e avvia in background la verifica AI delle righe. Il segno ✓ del passo 1 compare quando c’è (GOTO o titolo) e un sistema.' },
  { title: 'Passo 2 · Interventi', subtitle: 'Scegliere le voci di catalogo e il parere AI', intro: 'Il passo Interventi decide cosa entra nell’offerta. L’app mette in fila le voci importate dall’Excel e le possibili integrazioni del catalogo; tu scegli, regoli tipo, complessità e quantità, e puoi chiedere un secondo parere all’AI. Nulla viene aggiunto all’offerta finché non premi «Vai all’offerta».', steps: [
    'In alto il riquadro «Supporto AI alla valutazione» riassume quante valorizzazioni sono già previste nell’Excel e quante integrazioni si possono valutare, oppure quante componenti candidate ci sono nel Catalogo del lotto.',
    'Premi «Secondo parere AI» (poi «Aggiorna parere AI») per ottenere proposte e un riepilogo. Può richiedere 1–2 minuti: non chiudere la pagina. Il riepilogo si legge in «Leggi il riepilogo AI».',
    'Nelle «Proposte AI» premi «+ Aggiungi» sulle sole che sono pertinenti: la voce entra già selezionata, con nota «Proposta AI», e l’app salva in automatico. «Mostra snippet» compare se la proposta cita dei file.',
    'Nelle «Possibili integrazioni», raggruppate per ID_INTERVENTO, spunta le voci che vuoi tenere e imposta Tipo (REALIZZAZIONE o MODIFICA), Complessità, Q.tà (intero, minimo 1) e note. Vedi accanto i prezzi Semplice, Medio e Complesso e l’importo proposto.',
    'Se la voce che ti serve non è proposta usa «Aggiungi manualmente dal catalogo»: premi «Aggiungi» (diventa «Già aggiunta») e comparirà tra le «Voci aggiunte manualmente».',
    'Premi «Vai all’offerta»: il pulsante è spento se non hai selezionato nulla. Se una riga importata non ha prezzo, l’app avvisa «Completa i prezzi mancanti prima di comporre l’offerta» e non prosegue.',
  ], warnings: [
    ['Il banner in alto mostra GOTO, titolo, sistema e release.', 'Premi «← Modifica» per tornare ai dati dell’iniziativa senza perdere le scelte.'],
    ['«Vai all’offerta» è disattivato.', 'Seleziona almeno una voce, oppure importa una Tabella di Offerta con interventi.'],
    ['L’analisi AI non risponde.', 'Il pulsante resta occupato mentre lavora; attendi, poi riprova. Le scelte già fatte non vanno perse.'],
  ], note: 'Il passo 2 ha il ✓ quando c’è almeno un suggerimento selezionato o ci sono voci in offerta.' },
  { title: 'Passo 3 · Offerta', subtitle: 'Prezzi, TOW, sconto e contingenza', intro: 'Qui le voci scelte diventano un’offerta economica. Il totale è la somma delle voci di catalogo più le TOW (le attività trasversali, ad esempio gestione e collaudo) calcolate in percentuale sul catalogo o inserite a mano.', steps: [
    'In alto «Confronto Excel e Voci Catalogo» mostra come le righe importate si associano al catalogo, con la verifica AI e un totale originale a confronto con la base d’asta. Risolvi le associazioni incerte prima di fidarti dei prezzi.',
    'Nelle «Voci di catalogo» ogni riga ha Tipo, Complessità, Q.tà, Prezzo unitario, Totale e una nota per razionali e vincoli. «Espandi tutti» e «Chiudi tutti» aprono o chiudono i dettagli, e «×» rimuove la riga.',
    'Imposta «Sconto (%)» e «Contingenza (%)», se previsti. Sopra vedi la «Base TOW automatici», cioè catalogo × moltiplicatore della stima.',
    'Nei «TOW automatici» (TOW .1, .3 e .4 del lotto) regola la «% impatto»: l’importo è base × percentuale e la quantità equivalente è importo diviso prezzo unitario. Se il contratto ha percentuali salvate, scegli «% da contratto»: il segno ★ indica un valore preso da Gestione Contratto.',
    'Nei «TOW manuali» (TOW .2 e .6) inserisci Nome TOW, QTA e Valore unitario; il totale si calcola da solo.',
    'In fondo leggi «Totale catalogo», «Altri TOW» e «Totale offerta». Con «Revisione →» passi al passo 4; «← Interventi» torna indietro.',
  ], fields: { caption: 'Le tre sorgenti del totale', rows: [
    ['Voci di catalogo', 'Quantità × prezzo unitario secondo tipo e complessità, dal listino del catalogo selezionato.'],
    ['TOW automatici .1 .3 .4', 'Base TOW × % impatto. La % viene dal contratto (★) o la inserisci tu.'],
    ['TOW manuali .2 .6', 'QTA × Valore unitario inseriti a mano.'],
  ] }, warnings: [
    ['«Listino TOW per la stima»: quale scegliere?', 'La select «Contratto di origine dei prezzi TOW» parte da «Usa il listino del catalogo selezionato»; cambiala solo se i prezzi TOW vengono da un altro contratto.'],
    ['Quantità n.d.', 'Manca il prezzo unitario della TOW nel contratto: completalo in Gestione Contratto.'],
    ['Contratto e lotto non modificabili.', 'Con voci già in offerta sono bloccati per non mescolare cataloghi: per cambiarli svuota prima l’offerta.'],
  ], note: 'Il passo 3 ha il ✓ quando ci sono voci in offerta. I valori mostrati si aggiornano a ogni modifica, ma sono definitivi solo dopo «Salva valutazione».' },
  { title: 'Passo 4 · Revisione e salvataggio', subtitle: 'Controllare, esportare e salvare', intro: 'La Revisione è il riepilogo finale. Qui verifichi i numeri, produci i documenti da consegnare e salvi la valutazione. Il passaggio a questo passo salva già in automatico, senza messaggio, per non perdere il lavoro.', steps: [
    'Leggi la card «Revisione offerta»: lotto, voci di catalogo, sconto, contingenza, totale offerta e il dettaglio righe per intervento. Aggiungi le «Note economiche» se servono.',
    'Per la Tabella di offerta Excel apri «Tabella di offerta · Excel HLD»: scegli il «Modello Excel originale» (.xlsx con i due fogli) e premi «Genera Tabella di offerta XLSX». Scarichi «Tabella Offerta - {GOTO}.xlsx»; il modello originale non viene modificato.',
    '«Esporta JSON» ed «Esporta CSV» scaricano i dati dell’offerta (il CSV usa il punto e virgola e le colonne ID Catalogo, Tipo, Complessità, Quantità, Prezzo unitario, Importo, Intervento, Razionale). «Stampa» apre la stampa del browser.',
    'Premi «Salva valutazione» per registrare l’offerta e aggiornare lo storico dell’analisi. L’esito arriva solo dopo la conferma del server: «Valutazione salvata e resa disponibile alle stime future», oppure «Valutazione aggiornata con successo» se stavi modificandone una esistente.',
    '«Salva e Chiudi» (in alto a destra dello stepper) salva e svuota la pagina solo se il salvataggio riesce. «Salva e vai a Sviluppo →» salva e apre l’applicazione Sviluppo iniziative sulla stessa iniziativa.',
    'Se riapri una valutazione già salvata compare «Modalità modifica»: «Salva valutazione» la sovrascrive, mentre «Salva come nuovo» conserva l’originale.',
  ], warnings: [
    ['«Genera Tabella di offerta XLSX» è spento.', 'Servono il modello Excel, almeno una voce in offerta e il Codice GOTO.'],
    ['«Il template non contiene campi sconto/contingency».', 'Azzera sconto e contingenza oppure usa un modello che li rappresenti.'],
    ['«Il modello contiene solo TOW .1–.5».', 'Una TOW .6 valorizzata non è rappresentabile da quel modello: serve un modello adeguato.'],
    ['«Voce {id}: associazione o prezzo del contratto mancante».', 'Risolvi l’associazione nel «Confronto Excel e Voci Catalogo» del passo 3.'],
    ['«Un collega ha aggiornato lo storico».', 'Aggiorna lo storico dell’analisi, confronta la bozza e riprova: il lavoro corrente è conservato.'],
    ['«Offerta salvata, ma storico non aggiornato».', 'Il salvataggio è avvenuto a metà: la pagina resta aperta, conserva la bozza e riconcilia lo storico prima di chiudere.'],
    ['«Salvataggio non riuscito».', 'La pagina non si chiude: non ricaricarla, correggi il motivo indicato e riprova.'],
  ], note: 'Il salvataggio completo richiede il Codice GOTO. Controlla sempre l’Excel scaricato (totali, stampa, formattazione) prima della consegna.' },
  { title: 'Il passo Iniziativa: le sette sezioni', subtitle: 'Un percorso a righe apribili', steps: [
    'Il passo Iniziativa è composto da sette sezioni, sempre nello stesso ordine: 1 Dati iniziativa · 2 Workspace documentale · 3 Razionali e vincoli con l’AI · 4 Soluzione · 5 Analisi condivisa · 6 Codice sorgente · 7 Conoscenza dell’Iniziativa.',
    'Ogni sezione è una riga chiusa che mostra già il titolo e le informazioni principali (per esempio «5 documenti · 2 memorie iniziali», «3 confermate: 1 razionali · 2 vincoli», «2 di 5 interventi descritti»). Premi la riga per aprirla e rivederla per chiuderla. Puoi tenerne aperte più di una; all’apertura della pagina è aperta solo «Dati iniziativa».',
    'Se hai aperto un’iniziativa (codice GOTO o titolo) le sezioni 2, 3, 4 e 5 sono attive. Senza iniziativa la riga indica «Bloccato» e spiega cosa fare: non vengono caricati dati né fatte richieste.',
    'Chiudere una riga non fa perdere nulla: quello che hai scritto resta nella pagina. La sezione 7 riassume tutta la conoscenza raccolta e ogni scheda apre la sezione corrispondente.',
    'In «Dati iniziativa», accanto al titolo, trovi il pulsante «Importa Tabella di Offerta» (piccolo, perché si usa di rado): carica il workbook e compila dati e interventi. Il dettaglio dell’offerta importata e il confronto con il catalogo si trovano dentro la sezione 7.',
    'In «Dati iniziativa», accanto a «Release», c’è «PM Poste»: scegli il nome tra quelli già usati in MEV e MEV-CAP per il contratto attivo, così la stessa persona è scritta sempre allo stesso modo. Se il PM non è ancora presente scegli «Altro (testo libero)…» e scrivilo. Se l’elenco non è disponibile il campo diventa un normale campo di testo. Il valore viene salvato con l’offerta e con le revisioni dell’analisi, compare nella riga chiusa («PM …») e nel file della Soluzione.',
  ], note: 'L’ordine delle sezioni non è un obbligo: puoi lavorarci nell’ordine che preferisci. Per salvare l’offerta continuano a valere i comandi di Revisione.' },
  { title: 'Soluzione e download per Visual Studio Code', subtitle: 'Descrivere come si realizza ogni intervento', steps: [
    'La sezione 4 «Soluzione» mostra un intervento per riga (quelli della Tabella di Offerta importata). Apri una riga per vedere a sinistra i dettagli dell’intervento — descrizione, attività, copertura requisiti, tabella delle voci di catalogo con componente e tecnologia, razionali e vincoli confermati — che sono di sola lettura, e a destra i campi da compilare.',
    'I campi sono cinque: Soluzione proposta, Vincoli e dipendenze, Ipotesi da verificare, Verifiche e criteri di accettazione, Note per chi sviluppa. In alto c’è anche la «Sintesi generale» dell’intera iniziativa. Ogni campo ha un limite di 6.000 caratteri (la sintesi 1.500), con un contatore quando ti avvicini.',
    '«Salva soluzione» la salva per l’intera iniziativa, condivisa con il team, e conferma solo dopo il riscontro del server. Se un collega ha salvato dopo la tua apertura ricevi un conflitto e il tuo testo resta nella pagina: copialo, premi «Ricarica» e riconcilia. «Ricarica» chiede conferma se hai modifiche non salvate.',
    '«Scarica MD per Visual Studio Code» crea un file Markdown (SOLUZIONE_<codice>.md) con: dati dell’iniziativa, sintesi, applicativi coinvolti, e per ogni intervento descrizione, requisiti, tabella delle attività, razionali e vincoli confermati e il testo che hai scritto. Include anche le modifiche non ancora salvate che vedi in pagina. Aprilo in Visual Studio Code, o dallo Sviluppo come contesto per chi scrive il codice.',
    'Il filtro separa gli interventi con soluzione da quelli ancora da descrivere. Se un intervento esce dall’offerta dopo una nuova importazione, la sua soluzione NON viene cancellata: compare segnata «Non più nell’offerta» perché tu decida se è ancora valida.',
    'La Soluzione usa tutto ciò che il team ha condiviso in «Razionali e vincoli con l’AI». In alto vedi un riepilogo («3 confermati: 2 vincoli · 1 decisioni · 0 razionali, 2 proposte ancora da confermare»). Sotto ogni intervento compaiono i razionali, i vincoli e le decisioni confermati — prima i vincoli, poi le decisioni, poi i razionali — ciascuno con chi l’ha confermato e quando, se è stato proposto dall’AI o inserito da una persona e se è stato ripreso da un’altra iniziativa. Le voci non collegate a un intervento valgono per tutta l’iniziativa e compaiono sotto tutti gli interventi.',
    'Le proposte che l’AI ha fatto ma nessuno ha ancora confermato compaiono in un riquadro giallo «⚠ Da confermare — proposte non verificate», sia in pagina sia nel file: sono ipotesi, non requisiti. Per promuoverle a fatti confermali in «Razionali e vincoli con l’AI»: la Soluzione si aggiorna subito, senza ricaricare. Le voci scartate o revocate non compaiono mai. Il testo della conversazione con l’AI non viene copiato nel file.',
    'Il file Markdown ha quindi una sezione «Razionali e vincoli dell’iniziativa» con i conteggi e le voci valide per tutta l’iniziativa, e sotto ogni intervento le sue voci confermate e da confermare: chi sviluppa in Visual Studio Code ha il contesto, i vincoli da rispettare e sa quali punti sono ancora aperti.',
    'Chi ha solo il ruolo di consultazione può leggere e scaricare ma non modificare né salvare. Nel file non entrano le voci scartate o revocate.',
  ], note: 'La soluzione è scritta e rivista dal team: l’app non la genera e il file non è stato verificato sul codice. Le sezioni vuote indicano informazioni non ancora fornite.' },
  { title: 'Workspace documentale', subtitle: 'La memoria condivisa dell’iniziativa', steps: [
    'Nel passo Iniziativa, sotto «Razionali e vincoli con l’AI», trovi il «Workspace documentale». Serve un’iniziativa aperta (codice GOTO o titolo): senza, l’area è bloccata e non carica nulla. Ogni iniziativa ha il proprio archivio, separato per ambiente.',
    'Premi «Carica Documenti» oppure trascina i file nell’area tratteggiata: puoi sceglierne più di uno (fino a 5 per invio, i file in più partono in invii successivi) e ciascuno può pesare fino a 10 MB. Sono accettati PDF, Word, Excel, PowerPoint, testo, CSV, ZIP, RAR, EML, MSG, XML, JSON, immagini e altri formati documentali. I file eseguibili (.exe, .bat, .dll, .ps1 e simili) sono rifiutati. Alla fine un riepilogo dice, file per file, cosa è stato caricato e perché un file è stato rifiutato.',
    'Le cartelle sono: Memorie iniziali, Requisiti cliente, Analisi funzionali, Documentazione tecnica, Email e comunicazioni, Allegati ricevuti. Scegli la cartella prima di caricare oppure lascia «Automatica» (le email vanno in «Email e comunicazioni», il resto in «Allegati ricevuti») e sposta il documento dopo. «Versioni storiche» non è una cartella da scegliere: ogni versione sostituita ci finisce da sola e resta consultabile.',
    'Le «Memorie iniziali» sono la base di contesto permanente (standard, template, linee guida, lesson learned): l’AI le preferisce a parità di pertinenza. I requisiti, i verbali, le email e le specifiche dell’iniziativa vanno nelle altre cartelle.',
    'Quando tra i file scelti ci sono delle immagini (PNG, JPG, GIF, BMP, TIFF, WEBP) compare la domanda «Vuoi leggere il testo contenuto nelle immagini (OCR)?»: spunta le immagini da leggere, oppure «Usa OCR su tutte» o «Nessuna», poi «Carica con OCR su N» / «Carica senza OCR». Se non ci sono immagini la domanda non compare e il caricamento parte subito. L’OCR è una scelta tua per ogni immagine: richiede qualche secondo e può sbagliare, quindi va usato solo dove serve (uno screenshot con testo sì, una foto o un logo no). Gli SVG sono testo e non ne hanno bisogno.',
    'Con l’OCR il testo riconosciuto rende l’immagine ricercabile e utilizzabile dall’AI, con la posizione «OCR · riga N». Un’immagine caricata senza OCR resta ricercabile solo per nome; puoi leggerla dopo con «Leggi il testo (OCR)». Se il motore OCR non è installato sul server, il caricamento riesce comunque e il riepilogo lo dice (e la domanda ti avvisa prima). Il riconoscimento è in italiano e inglese; verifica sempre il testo sull’immagine.',
    'Un file con lo stesso contenuto di uno già presente non viene caricato due volte. Un file con lo stesso nome ma contenuto diverso non sostituisce il precedente da solo: usa «Sostituisci / nuova versione» (o «Carica come nuova versione» nel riepilogo) per mantenere lo storico. Se un collega ha caricato una versione nel frattempo ricevi un conflitto e non viene scritto nulla.',
    '«Storia» mostra tutte le versioni (con download di ciascuna) e chi ha fatto cosa e quando: caricato, nuova versione, cartella cambiata, uso AI, eliminazione. «Elimina» è logico: il documento sparisce dall’elenco, dalla ricerca e dalle risposte AI ma gli originali restano conservati; lo può fare chi ha caricato la versione corrente o un amministratore.',
    'Ogni documento è indicizzato appena caricato, quando il formato lo consente: PDF con testo, Word (docx), Excel (xlsx), PowerPoint (pptx), testo, CSV, XML, JSON, HTML ed email (.eml, con intestazioni e nomi degli allegati). Di ZIP si indicizzano solo i nomi dei file contenuti. Immagini e PDF scansionati non hanno testo leggibile senza OCR; DOC/XLS/PPT vecchi, MSG e RAR non sono leggibili: restano ricercabili per nome e il badge ne spiega il motivo. L’OCR è disponibile solo per le immagini; i PDF scansionati non vengono letti con OCR.',
    'Gli allegati caricati prima di questa funzione compaiono nella cartella «Allegati ricevuti» come versione 1; per renderli ricercabili premi «Indicizza ora» nell’avviso giallo.',
    '«Cerca nei documenti» cerca nel nome e nel contenuto, ignorando maiuscole e accenti e trovando anche singolare e plurale (requisito/requisiti). Puoi filtrare per cartella, autore e intervallo di date di caricamento, e includere le versioni precedenti. I risultati mostrano un estratto con le parole trovate evidenziate.',
    '«Chiedi ai documenti» interroga l’AI sul contenuto dell’iniziativa: il sistema seleziona i passaggi pertinenti dei soli documenti correnti e abilitati all’AI della tua iniziativa, li passa all’AI e mostra la risposta con le fonti numerate [1], [2]…. Se nessun passaggio è pertinente l’AI non viene interpellata e te lo dice. Verifica sempre la risposta sulle fonti.',
    '«Escludi dall’AI» toglie un documento da ogni uso AI (risposte ai documenti, parere sull’offerta, chat dei razionali) senza eliminarlo; «Usa nell’AI» lo riattiva. Il parere AI sull’offerta e la chat dei razionali usano automaticamente i passaggi più pertinenti dei documenti dell’iniziativa aperta.',
  ], note: 'I documenti sono visibili a chi lavora sull’iniziativa nello stesso ambiente: non caricare credenziali o dati che non devono essere condivisi. Chi ha solo il ruolo di consultazione (per esempio Bid Manager) può cercare, leggere e scaricare ma non caricare, modificare o interrogare l’AI. Il testo estratto è automatico e può contenere errori: l’originale resta la fonte.' },
  { title: 'Razionali e vincoli con l’AI', subtitle: 'Spiegare perché servono gli interventi', steps: [
    'Nel passo Iniziativa, sotto «Dati iniziativa», trovi «Razionali e vincoli con l’AI». Serve il codice GOTO o il titolo. Scrivi all’AI, direttamente nell’area azzurra, perché servono gli interventi, quali vincoli tecnici o di processo valgono, cosa è già stato deciso. A conversazione vuota l’area è tutta di scrittura; man mano che si riempie, in alto compare lo storico e la casella resta in basso. Invio per inviare, Maiusc+Invio per andare a capo.',
    'L’AI risponde e può proporre voci di tre tipi: razionale (perché serve), vincolo (cosa limita) e decisione (cosa è stato scelto). Le voci proposte compaiono in «Da confermare»: puoi correggerne il testo, poi «Conferma» o «Scarta». L’AI non conferma mai da sola.',
    'Solo le voci confermate sono conoscenza: vengono date al parere AI sull’offerta, alla verifica AI di ogni riga, alle proposte di scheda, alla generazione dei file e agli ZIP di Sviluppo. Le proposte, le scartate e le revocate non vengono mai usate. Una voce collegata a un intervento vale per quell’intervento; una non collegata vale per l’intera iniziativa.',
    '«Aggiungi una voce a mano» crea subito una voce confermata, perché la decide una persona. «Revoca» toglie una voce confermata dall’uso futuro (chiede conferma); la voce resta nello storico.',
    'Sotto la conversazione, una sola riga «Conoscenza dell’iniziativa» riassume quante voci hai in «Da confermare», «Confermate», «Da altre iniziative» e «Scartate». Cliccala per aprire gli elenchi: si apre da sola quando l’AI propone qualcosa da decidere.',
    'Per far guardare all’AI il tuo codice premi «Seleziona cartella sorgenti» e scegli la cartella sul tuo computer. Il browser non può leggere un percorso scritto a mano e il server non vede il tuo disco, quindi la cartella resta sul tuo computer e va riselezionata a ogni sessione. A ogni domanda l’app sceglie i file pertinenti, secondo le parole della domanda, e invia all’AI solo alcuni estratti (al massimo 8 allegati e 20.000 caratteri). È un campione, non un’analisi completa del repository.',
    '«Incolla dati (es. risultato di una query)» allega alla prossima domanda un testo che incolli (al massimo 4.000 caratteri), ad esempio le righe che hai ottenuto interrogando un database. Gli allegati valgono solo per quella domanda e non vengono salvati con la conversazione.',
    'Prima dell’invio ogni allegato è controllato: se contiene una credenziale (password, token, chiave, indirizzo con utente e password) non parte. L’app dice quale allegato e su quale riga, senza mai riportare il valore; il testo incollato viene cancellato dalla casella.',
    '«Collegamento a un ambiente Poste» spiega come lavorare con i dati di un ambiente raggiungibile solo in VPN. L’applicazione è su Internet e non può aprire la tua VPN né collegarsi ai database di Poste: la VPN la apri tu dal tuo computer, esegui la query e incolli il risultato nella conversazione. Gli appunti (ambiente, VPN, database, chi concede l’accesso) restano solo nel tuo browser e non contengono credenziali.',
    '«Da altre iniziative» mostra le voci confermate in altre iniziative dello stesso ambiente e dello stesso sistema. «Riprendi in questa iniziativa» le copia come proposte, ricordando l’origine: devi confermarle tu, perché possono non valere qui. Così un nuovo intervento sullo stesso sistema parte dalle logiche già stabilite.',
    'La conversazione è unica per iniziativa e ambiente, conservata nel tempo e visibile ai colleghi che lavorano sull’iniziativa. I messaggi più vecchi si caricano con «Mostra messaggi precedenti». Se l’AI non risponde, il tuo messaggio resta salvato.',
  ], note: 'Le risposte dell’AI sono proposte da verificare, non fatti. Non scrivere password, chiavi o dati riservati: la cronologia è visibile ai colleghi dello stesso ambiente. Non cambiano prezzi né stime: orientano l’analisi e lo sviluppo.' },
  { title: 'Archivio e creazione', subtitle: 'Ritrovare e riprendere il lavoro', steps: [
    'Apri “Archivio iniziative”: le analisi condivise e le offerte salvate sono presentate in sezioni distinte. Clicca una scheda per aprirla.',
    'Una revisione condivisa conserva analisi e snapshot economico. La riapertura recupera i dati disponibili; un catalogo non più disponibile impedisce il ripristino dello snapshot.',
    '“Nuova Iniziativa” svuota il lavoro corrente dopo conferma se sono presenti dati. Salva prima le modifiche da conservare.',
  ] },
  { title: 'Storico delle iniziative', subtitle: 'Lo stato di tutte le iniziative, sempre aggiornato', steps: [
    'In alto a destra, accanto al Manuale, l’icona dell’orologio “Storico iniziative” apre un pannello con tutte le iniziative: rilasciate, rilasciate parzialmente, approvate, in approvazione, in analisi/stima e CR da stimare. Il numero accanto all’icona è il totale. Il pannello si apre sopra tutta la pagina, barra in alto compresa, e si chiude con ✕, con Esc o cliccando fuori.',
    'Le schede per stato sono cliccabili e filtrano l’elenco; la ricerca e i filtri per sistema, PM Poste e release si possono combinare. “Archiviate” mostra le iniziative messe da parte.',
    'Per caricare o aggiornare lo storico usa “Importa file .md” con il file dello stato delle iniziative. Prima di salvare vedi un’anteprima: quante iniziative sono nuove, aggiornate o invariate, e le eventuali righe da controllare. Nulla viene salvato finché non confermi.',
    'L’identità di un’iniziativa è GOTO + sistema + titolo: lo stesso GOTO può comparire su più sistemi. Se il GOTO è “TBD” l’iniziativa è riconosciuta da sistema e titolo e, quando il codice arriva, basta importare il file con il GOTO vero: l’iniziativa esistente viene aggiornata, non duplicata.',
    'L’importazione non cancella mai: un campo vuoto nel file non svuota quello già presente, le iniziative assenti dal file restano, e un file più vecchio di quanto già registrato compila solo i campi mancanti senza riportare indietro la data.',
    'Ogni iniziativa si apre in una scheda con i dati modificabili (stato, release, PM Poste, collaudo, note, cosa è rilasciato e cosa manca) e la cronologia: cambi di stato, importazioni, note e attività, con chi e quando e il valore precedente e quello nuovo. Se un collega modifica la stessa iniziativa prima di te, il salvataggio è rifiutato e il tuo testo resta sullo schermo.',
    '“Apri nel Configuratore” porta GOTO, titolo, sistema, release e PM Poste nell’iniziativa in lavorazione; se ne hai già una aperta ti viene chiesta conferma. “Scarica .md aggiornato” produce il file dello stato nello stesso formato di quello importato. Importare, creare, modificare e archiviare sono riservati a chi può lavorare sulle iniziative; gli altri possono consultare e scaricare.',
    'Lo storico non si aggiorna da solo quando salvi un’offerta o una soluzione: le attività che vuoi ricordare si aggiungono dalla scheda come “Attività” o “Nota”.',
  ] },
  { title: 'Conoscenza storica dall’AI', subtitle: 'Riutilizzare il lavoro già fatto con gli assistenti', steps: [
    'Accanto allo Storico, il pulsante viola “Conoscenza storica AI” importa i razionali, i vincoli e le decisioni già scritti nelle note degli assistenti AI (file Markdown). Il numero sotto il pulsante è quante voci aspettano una conferma.',
    'Prepara due file: l’archivio della cartella “projects” del backup (.zip, .tar.gz, .tgz o .tar) e l’elenco dei percorsi (un file .txt con un percorso per riga; vanno bene anche le liste con più colonne separate da tabulazione, come NUOVO o MODIFICATO prima del percorso). L’archivio viene aperto nel tuo browser e non viene caricato: partono verso il server solo le note Markdown che superano i controlli. I file .jsonl (le trascrizioni complete) non vengono mai letti. Le note che l’elenco segna ESCLUSO-RISERVATO sono lasciate fuori di proposito: non vengono lette né segnalate come mancanti.',
    '“Controlla i file” mostra un’anteprima senza inviare nulla all’AI: quante note verranno lette, quante scartate per credenziali, quante già lette da un collega o non pertinenti, e il numero per sistema. Il sistema si ricava dal nome della nota (ilp-, npso-, bep-, iper-, ipersuite-, is-, sc-…). Se non c’è nessuna nota da leggere, l’anteprima si apre da sola sui motivi: per ogni gruppo dice perché le note non vengono lette (credenziali, indici e note di sessione, già lette, nome senza sistema noto, assenti dall’archivio) e ne elenca i primi nomi.',
    'Prima di tutto ogni nota passa un controllo sulle credenziali (password, token GitHub e OpenShift, JWT, chiavi private, indirizzi con utente e password). Una nota con una credenziale non viene letta né inviata: il rapporto scaricabile dice quale file, quale tipo di credenziale e quale riga, senza mai riportare il valore. Le note di accessi sono lette in modo più severo: se una nota è fermata solo da questo controllo prudenziale il rapporto la segna “da verificare”, perché potrebbe essere innocua. Le credenziali già presenti nel backup vanno comunque ruotate: questo controllo non le rimuove da dove sono.',
    'Restano fuori per scelta, con il motivo nel rapporto: gli indici (MEMORY), le note di sessione, le preferenze di lavoro e gli ambienti personali dell’assistente, i dati personali. Due note con lo stesso contenuto vengono lette una volta sola, anche con nomi diversi, e una nota già letta da un collega non viene riletta.',
    '“Leggi N note con l’AI” invia una nota alla volta usando la tua configurazione AI. L’AI propone solo ciò che dura nel tempo (perché, vincoli, decisioni) e ignora cronaca, commit e avanzamento. Se l’AI non risponde per tre note di fila la lettura si ferma da sola e te lo dice; puoi anche fermarla tu. Le note già lette restano e quando rilanci vengono saltate.',
    'Nulla nasce confermato. Ogni voce arriva “da confermare”, con il file di origine e l’autore. Nell’elenco in fondo scegli le voci (o “Seleziona tutte”) e usi “Conferma” o “Scarta”; si decide al massimo 100 voci per volta. Una voce confermata viene proposta alle altre iniziative dello stesso sistema, che la riprendono come proposta.',
    'Per rivedere quanto è stato importato, anche dopo essere usciti dall’app, apri la scheda “Cosa è stato importato”: elenca le voci confermate (o scartate, o ancora da confermare) con il testo, il sistema, il tipo, la nota di origine, l’autore e chi le ha confermate e quando. Si può cercare nel testo o nel nome della nota e filtrare per sistema e tipo; l’elenco è in sola lettura.',
    'Senza un GOTO chiaro nella nota, le voci sono legate al sistema (“Storico ILP”). Se la nota cita un solo GOTO più volte, la voce è legata a quell’iniziativa. Importare, confermare e scartare è riservato a chi può lavorare sulle iniziative; gli altri possono solo consultare. Per importare il lavoro di un collega, importa il suo zip con il suo elenco dal tuo computer: le voci riportano l’autore della cartella.',
  ] },
  { title: 'Contratto e listino', subtitle: 'Scegliere la fonte economica corretta', steps: [
    'In “Risorse e configurazione” scegli il «Contratto del catalogo» e il «Lotto catalogo». C’è un solo elenco di contratti, quello dell’Archivio contrattuale: la prima volta l’app sceglie da sola il contratto e il lotto collegati al codice contratto del tuo ambiente.',
    'Quando la stima contiene righe, la selezione del catalogo è bloccata. Per un altro contratto avvia una nuova iniziativa.',
    'In Offerta o Revisione controlla il “Listino TOW per la stima”. Se il listino è su un diverso record contrattuale dell’Archivio, scegli esplicitamente il “Contratto di origine dei prezzi TOW”.',
    'Verifica che i prezzi unitari siano disponibili. Percentuali di impatto, pesi contrattuali e prezzi unitari sono dati diversi: non sono intercambiabili.',
  ], note: 'Il modello Excel non viene usato come ripiego per i prezzi. Se compare “Quantità n.d.”, l’importo percentuale può essere calcolato ma manca il prezzo per ottenere la quantità equivalente.' },
  { title: 'Importazione Excel', subtitle: 'Riepilogo interventi e DettaglioInterventi', steps: [
    'Usa “Importa Tabella di Offerta” nel passaggio Iniziativa. Il workbook deve contenere il foglio di riepilogo dell’iniziativa e il foglio “DettaglioInterventi” con le intestazioni originali.',
    'Il riepilogo identifica interventi, attività, sistema e requisiti. DettaglioInterventi contiene le singole componenti, voce catalogo, tipo, complessità, quantità e prezzi.',
    'L’importazione crea una revisione con nome del file e snapshot dei dati. Una nuova importazione sullo stesso GOTO aggiunge una revisione senza riscrivere analisi e decisioni già salvate.',
    'In “Mostra dettaglio importato” apri un ID_INTERVENTO per consultarne le componenti. Il totale nell’intestazione somma quantità × prezzo in uso delle componenti; un prezzo assente rende il totale non disponibile.',
  ], note: 'La verifica AI parte dopo l’importazione. Un errore AI non annulla i dati importati. Se il salvataggio della revisione fallisce, viene segnalato: salva dal workspace dopo aver controllato lo storico.' },
  { title: 'Catalogo e verifica AI', subtitle: 'Validare attività e importi, una riga alla volta', steps: [
    'In “Confronto Excel e Voci Catalogo” scegli la vista Interventi oppure Voce catalogo. Apri il gruppo e poi l’intervento o la voce per vedere le attività associate.',
    'La verifica AI è subito dopo Voce catalogo: leggi esito, motivazione, indicazione ed evidenze. “Coerente secondo AI” è un parere, non un’approvazione umana o una certificazione del codice.',
    'In “Possibili integrazioni” ogni proposta è una voce del catalogo che potrebbe servire all’intervento indicato. Leggi il nome, l’ambito e il motivo della proposta, poi verifica che l’attività non sia già coperta. Selezionala solo se pertinente. Il codice driver-… consultabile nei riferimenti tecnici identifica la voce nel sistema: non è un ID intervento o contratto e non richiede azioni.',
    'Dopo modifiche ai dati usati dal controllo, il risultato è marcato “Da aggiornare”. Premi “Verifica / aggiorna coerenza AI delle righe”. Errori e risposte non valide sono mostrati per riga.',
    'L’associazione indica quale voce del catalogo contrattuale rappresenta le attività del file. ID Excel è il codice nel workbook; ID Intervento raggruppa le attività; il contratto è il contesto economico scelto. Un codice driver-… è solo il riferimento tecnico della singola voce, non l’ID del contratto: non devi compilarlo.',
    'Esempio: 58 righe Excel con codice 242 e nome “Realizzazione stored procedure o equivalente” possono essere collegate alla voce “Realizzazione stored procedure, script SQL o equivalente”. Il sistema riconosce i codici o un nome univoco con ambito compatibile; la somiglianza non certifica la correttezza tecnica delle 58 attività. Controlla le attività e il parere AI.',
    'Se l’associazione attuale è corretta, non serve confermarla: è già usata per il confronto. Se manca o è errata, scegli la voce corretta, leggine descrizione e criteri e conferma. Il collegamento cambia per tutte le righe di questa offerta con lo stesso codice Excel, ma non modifica attività, quantità, tipo, complessità o prezzi. Se le righe richiedono voci diverse, non confermare un’associazione unica: correggi prima il dettaglio di origine.',
    '“Mostra dettagli e importi” rende visibili tipo/complessità, quantità e prezzi. “Usa catalogo” aggiorna il prezzo della singola riga. L’associazione da sola non aggiorna i prezzi.',
  ], note: 'Salva una valutazione o una revisione per conservare i pareri ricevuti. Nessuna risposta simulata dei test entra nelle iniziative reali.' },
  { title: 'Documenti e fonti', subtitle: 'Dall’originale al contesto selezionato', steps: [
    'Carica gli allegati in “Documentazione ricevuta” (massimo 10 MB per file). Ogni originale ha identificativo, autore, data e impronta SHA-256. Un nome uguale non sovrascrive l’allegato precedente.',
    'Premi “Estrai testo” per PDF testuali, DOCX, XLSX e formati di testo supportati. “Consulta estratto salvato” recupera il testo già estratto.',
    'Usa ricerca e navigazione del lettore. Seleziona le sezioni pertinenti e premi “Usa sezioni selezionate nel contesto AI”. I checkbox da soli non inviano il testo all’AI.',
    'Il contesto documentale ammette fino a 48.000 caratteri; l’estrazione fino a 500.000 per documento. Parti non lette, errori e formati non supportati sono segnalati. Immagini e PDF scansionati non hanno OCR in questa versione.',
    '“Collega alle fonti dell’analisi” aggiunge il riferimento testuale. “Elimina allegato” lo rimuove dall’elenco attivo e dalla selezione AI della tua bozza; le revisioni precedenti e gli originali citati restano conservati.',
  ], note: 'Caricare, estrarre e includere nel contesto AI sono tre operazioni distinte. Salva la revisione per conservare le fonti selezionate.' },
  { title: 'Analisi e conversazione', subtitle: 'L’AI propone, gli specialisti decidono', steps: [
    'Compila AS-IS, TO-BE, fatti verificati, ipotesi e punti da confermare con Poste. Collega le fonti alle conclusioni e documenta i riferimenti a repository e interrogazioni.',
    'Salva una revisione prima di inviare una domanda nel “Confronto AI condiviso”. La richiesta usa l’ultima revisione salvata e gli ultimi sei scambi, con la configurazione AI personale dell’utente.',
    'Domande e risposte sono condivise per GOTO e ambiente, con autore, data, modello e revisione. “Consulta contesto usato” mostra lo snapshot inviato. La cronologia completa rimane consultabile.',
    'Puoi portare una proposta AI nelle decisioni da valutare. Controlla testo e fonte, approva esplicitamente quando opportuno e salva una nuova revisione. La proposta non è approvata automaticamente.',
  ], note: 'Repository e query indicati manualmente non equivalgono ad accessi Git/VPN eseguiti. La ricerca di memoria correlata usa sistema o famiglia: non è una ricerca semantica sull’intero archivio.' },
  { title: 'Revisioni e collaborazione', subtitle: 'Salvare, confrontare e approvare', steps: [
    'In “Modifiche e motivazione della revisione” descrivi cosa è cambiato e perché. “Salva nuova revisione con stima corrente” conserva analisi, decisioni, fonti e snapshot economico. “Salva valutazione” e “Salva e Chiudi” aggiornano l’offerta e la revisione condivisa e confermano il salvataggio solo dopo il riscontro del server. Se viene segnalato un salvataggio parziale o un conflitto, non ricaricare: la pagina resta aperta per conservare il lavoro. Schede di sviluppo, progetto di avvio e richiesta di modifica codice non si modificano più qui: si trovano nell’applicazione Sviluppo iniziative della Home.',
    '“Aggiorna storico senza perdere la bozza” recupera le nuove revisioni. Confronta due versioni nello storico. “Riprendi analisi e stima” sostituisce la bozza dopo conferma ma conserva le versioni già salvate.',
    'Se un collega ha già salvato dalla tua stessa versione, ricevi un conflitto. Non ricaricare la pagina: conserva la tua bozza, aggiorna lo storico e riconcilia le modifiche prima di salvare.',
    'Admin, Developer e SuperAdmin lavorano sulle analisi. Bid Manager e SuperAdmin possono approvare la revisione salvata. Le decisioni approvate non si riscrivono: documenta un cambiamento con una nuova decisione.',
  ], note: 'La collaborazione è asincrona con controllo dei conflitti, non co-editing in tempo reale. “Salva valutazione” conserva l’offerta nell’archivio esistente; le revisioni workspace conservano anche lo storico delle analisi.' },
  { title: 'Offerta ed export HLD', subtitle: 'Valorizzare e produrre il workbook', steps: [
    'In Offerta verifica le righe a catalogo e le percentuali TOW .1, .3 e .4 associate al contratto. L’importo è valore catalogo × moltiplicatore della stima × percentuale / 100; la quantità equivalente è importo / prezzo unitario.',
    'TOW .2 e .6 sono manuali. Nell’export del modello a cinque TOW, .2 viene ripartita fra gli interventi in proporzione al valore catalogo. Una TOW .6 valorizzata non è rappresentabile da quel modello.',
    'In Revisione seleziona il modello XLSX originale con i due fogli e premi “Genera Tabella di offerta XLSX”. Non inserire le percentuali come quantità manuali nell’export.',
    'Il generatore sostituisce i dati di esempio, adatta le righe e collega il riepilogo al dettaglio tramite formule. Usa i prezzi del catalogo selezionato e il listino TOW scelto; prezzi mancanti o associazioni non risolte bloccano l’export con un messaggio.',
    'Il modello attuale non rappresenta sconto, contingency e TOW .6: se valorizzati, occorre un modello adeguato. Controlla il file scaricato in Excel prima della consegna, inclusi totali, stampa e formattazione.',
  ], note: 'L’export non modifica l’originale scelto. Sono disponibili anche le esportazioni JSON e CSV. Per passare allo sviluppo premi “Salva e vai a Sviluppo →” in Revisione.' },
];

export function UserManual({ chapters, title, subtitle, triggerLabel = 'Manuale d’uso', triggerHint = 'Guida alla sezione', compact = false }) {
  const [open, setOpen] = useState(false);
  const [chapter, setChapter] = useState(0);
  const dialog = useRef(null);
  const content = useRef(null);
  const titleId = useId();
  useEffect(() => {
    if (!open) return;
    const element = dialog.current;
    element.showModal();
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { element.close(); document.body.style.overflow = overflow; };
  }, [open]);
  const current = chapters[chapter];
  return <>
    <button type="button" className={`tow-manual-trigger${compact ? ' tow-manual-trigger-compact' : ''}`} onClick={() => setOpen(true)} aria-haspopup="dialog">
      <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7"><path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1zM12 5v15"/></svg>
      <span>{triggerLabel}{!compact && <small>{triggerHint}</small>}</span>
    </button>
    {open && createPortal(<dialog ref={dialog} className="tow-manual" aria-labelledby={titleId} onCancel={() => setOpen(false)} onClose={() => setOpen(false)}>
      <header className="tow-manual-header"><div><span>GUIDA OPERATIVA</span><h2 id={titleId}>{title}</h2><p>{subtitle}</p></div><button type="button" autoFocus aria-label="Chiudi manuale" onClick={() => setOpen(false)}>✕</button></header>
      <div className="tow-manual-layout"><nav aria-label="Indice del manuale">{chapters.map((entry, index) => <button type="button" key={entry.title} aria-current={chapter === index ? 'page' : undefined} onClick={() => { setChapter(index); content.current?.scrollTo({ top: 0 }); }}><span>{String(index + 1).padStart(2, '0')}</span>{entry.title}</button>)}</nav>
        <article ref={content} className="tow-manual-content"><span className="tow-manual-section-number">Capitolo {chapter + 1} di {chapters.length}</span><h3>{current.title}</h3><p className="tow-manual-subtitle">{current.subtitle}</p>{current.intro && <p className="tow-manual-intro">{current.intro}</p>}<Figure figure={current.figure} />{current.highlights && <div className="tow-manual-highlights">{current.highlights.map(card => <section key={card.title}><strong>{card.title}</strong><p>{card.text}</p></section>)}</div>}<ol>{current.steps.map((step, index) => <li key={index}>{step}</li>)}</ol>{current.fields && <div className="tow-manual-fields"><table><caption>{current.fields.caption}</caption><thead><tr><th scope="col">Voce</th><th scope="col">Cosa fare</th></tr></thead><tbody>{current.fields.rows.map(([name, text]) => <tr key={name}><th scope="row">{name}</th><td>{text}</td></tr>)}</tbody></table></div>}{current.warnings && <div className="tow-manual-warnings"><strong>Se qualcosa non va</strong><ul>{current.warnings.map(([problem, fix]) => <li key={problem}><b>{problem}</b> {fix}</li>)}</ul></div>}{current.note && <aside><strong>Da ricordare</strong><p>{current.note}</p></aside>}<footer><button type="button" disabled={chapter === 0} onClick={() => { setChapter(chapter - 1); content.current?.scrollTo({ top: 0 }); }}>← Precedente</button><button type="button" disabled={chapter === chapters.length - 1} onClick={() => { setChapter(chapter + 1); content.current?.scrollTo({ top: 0 }); }}>Successivo →</button></footer></article>
      </div>
    </dialog>, document.body)}
  </>;
}

export default function ConfiguratorManual() {
  return <UserManual chapters={chapters} title="Configuratore Iniziative" subtitle="Dall’iniziativa alla proposta tecnica ed economica." triggerHint="Guida al configuratore" />;
}
